  from public.use_cases
 where project_id = (select id from public.projects where code = 'GPDN_DNMB_EVNNPC_QTVT_251004')
   and code in ('VP-I', 'UC-134', 'VP-II', 'UC-135', 'UC-136', 'VP-III', 'UC-137', 'VP-IV', 'UC-138', 'VP-V', 'UC-139', 'VP-VI', 'UC-140', 'UC-141', 'VP-VII', 'UC-142', 'UC-143', 'VP-VIII', 'UC-144', 'VP-IX', 'UC-145', 'UC-146', 'VP-X', 'VP-X.1', 'UC-147', 'VP-X.2', 'UC-148', 'UC-149', 'UC-150', 'VP-XI', 'UC-151', 'UC-152', 'UC-153', 'UC-154', 'UC-155', 'UC-156')
 group by kind
 order by kind;
